import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"复用 Identity 与账号事务","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/registration","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/registration.md","filePath":"tutorials/registration.md"}'),n={name:"tutorials/registration.md"};function r(o,a,l,p,h,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="复用-identity-与账号事务" tabindex="-1">复用 Identity 与账号事务 <a class="header-anchor" href="#复用-identity-与账号事务" aria-label="Permalink to &quot;复用 Identity 与账号事务&quot;">​</a></h1><p>目标：让自己的 SaaS 使用 Core 注册和凭据，不在业务模块重写密码、User 或 Membership。前提是<a href="./../getting-started/quickstart">快速开始</a>的 API 和 PostgreSQL 已运行；命令在仓库根目录执行。</p><h2 id="接入身份入口" tabindex="-1">接入身份入口 <a class="header-anchor" href="#接入身份入口" aria-label="Permalink to &quot;接入身份入口&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/lib.rs" target="_blank" rel="noreferrer">Core Router</a>已装配 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer">Identity</a>入口：<code>POST /api/v1/auth/register</code>、<code>POST /api/v1/auth/login</code>、<code>GET /api/v1/auth/session</code>。注册输入为 <code>email</code>、<code>password</code>、可选 <code>display_name</code>，角色由服务端决定。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/api/v1/auth/session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registration</span></span></code></pre></div><p>匿名请求得到 401 和 request_id。公开注册检查通过真实 Router 创建账号、取得 Cookie、查询身份，验证首位 Owner 和后续 Member。完整请求见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/tests/registration.rs" target="_blank" rel="noreferrer">注册 HTTP 测试</a>，DTO 见<a href="./../reference/api">API 参考</a>。业务 Handler 的接入在<a href="./sessions">下一页</a>。</p><h2 id="事务与提交边界" tabindex="-1">事务与提交边界 <a class="header-anchor" href="#事务与提交边界" aria-label="Permalink to &quot;事务与提交边界&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/migrations/0002_identity.sql" target="_blank" rel="noreferrer">Identity 迁移</a>包含账号、凭据、成员身份、会话和审计。注册在同一个事务创建 User、Credential、Membership 和 Audit，失败全部回滚。成员准入使用 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">Organization</a>的公共接口：</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> enroll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    connection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;mut</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PgConnection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MemberRole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, sqlx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span></code></pre></div><p>这是接口摘录。唯一 Organization 行串行化首次 Owner 初始化；请求不能指定 Owner。一次部署服务一个 Organization，自己的业务不会创建另一层租户，见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">ADR</a>。</p><p>账号事务提交后才签发 Session。失败返回 <code>auth.session_unavailable</code>，账号已存在，应通过登录恢复；重复注册不会覆盖密码、角色或停用状态。</p><h2 id="密码与秘密边界" tabindex="-1">密码与秘密边界 <a class="header-anchor" href="#密码与秘密边界" aria-label="Permalink to &quot;密码与秘密边界&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/crypto.rs" target="_blank" rel="noreferrer">密码实现</a>使用 Argon2id 和随机 salt，阻塞计算最多并发 4 个，满容量返回可重试 503。密码为 12–128 字符。邮箱去除两端空白、按小写唯一，不折叠 <code>+tag</code> 或点号；并发同邮箱只能一个成功。</p><p>Session 是 256-bit 随机 secret，数据库只存 SHA-256。HTTPS Cookie 为 <code>__Host-saas_session</code>，带 Secure、HttpOnly、SameSite=Lax、Path=/，不设 Domain；loopback HTTP 仅用于开发。secret 不进入业务 JSON、日志或浏览器存储。</p><p>注册要求匹配受信 <code>APP_ORIGIN</code>，不从请求 Host 推导。JSON 最大 16 KiB、读取最多 3 秒；账号事务预算 3 秒，Session 签发另有 2 秒。响应为 no-store；成功响应丢失不代表账号未创建，不自动重发注册 POST。</p><h2 id="验证并适配" tabindex="-1">验证并适配 <a class="header-anchor" href="#验证并适配" aria-label="Permalink to &quot;验证并适配&quot;">​</a></h2><p>注册检查覆盖邮箱冲突、首次 Owner 并发、Audit 回滚、Cookie、凭据存储和来源拒绝。Audit 失败时不应留下账号；账号已提交而 Session 失败时应能随后登录。</p><p>自己的业务表引用 User ID，并检查当前成员资格。需要客户资料初始化时先定义哪些事实必须同事务提交，再使用公共能力；业务资料规则留在自己的模块。继续<a href="./sessions">Session、Origin 与 CSRF</a>，再接入业务事务与幂等。</p><p>完整参考：<a href="./personal-documents">业务事务与幂等</a>。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/02-registration.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,21)])])}const b=s(n,[["render",r]]);export{k as __pageData,b as default};
